1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Rejects a new owner who belongs to the same household as an existing owner — same last name and same
13	 * address — so the request is answered with a 409 Conflict rather than persisting a duplicate household
14	 * member. Last name and address are compared case-insensitively with surrounding and internal whitespace
15	 * collapsed, so "Smith" / " smith " and "10  Main St" / "10 Main St" collide.
16	 *
17	 * <p>The caller can opt in to sharing a household by setting {@code sharesHousehold} true on the request,
18	 * which skips this check (e.g. a spouse or flatmate registering under the same roof). Runs after
19	 * {@link CheckTelephoneUnique} and before {@link BuildOwner}.
20	 */
21	public class CheckHouseholdUnique {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateHouseholdException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	        String lastName = normalize(request.getLastName());
29	        String address = normalize(request.getAddress());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (lastName.equals(normalize(existing.getLastName()))
32	                    && address.equals(normalize(existing.getAddress()))) {
33	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
34	            }
35	        }
36	    }
37	
38	    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
39	    private static String normalize(String value) {
40	        if (value == null) {
41	            return "";
42	        }
43	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
45	}
