1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a new owner whose E.164 telephone is already used by another owner, so the request is
11	 * answered with a 409 Conflict rather than persisting a duplicate. Runs after {@link ValidateNewOwner}
12	 * (which has already normalized the request telephone to E.164) and before {@link BuildOwner}.
13	 *
14	 * <p>Stored telephones are normalized to E.164 the same way before comparison so seed data that was
15	 * not stored in E.164 form still collides with an equivalent request.
16	 */
17	public class CheckTelephoneUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            String existingTelephone = existing.getTelephone();
24	            if (existingTelephone != null
25	                    && telephone.equals(OwnerTelephone.toE164(existingTelephone))) {
26	                throw new DuplicateTelephoneException(telephone);
27	            }
28	        }
29	    }
30	}
