1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a request to create an owner has the same last name and address (compared
5	 * case-insensitively with collapsed whitespace) as an owner that already exists, i.e. another member
6	 * of the same household, without opting in via {@code sharesHousehold}. Carries the offending last name
7	 * and address so {@link DuplicateHouseholdExceptionHandler} can report them. Checked so it appears in
8	 * the function's {@code throws} clause and is routed as an escalation (a 409 Conflict).
9	 */
10	public class DuplicateHouseholdException extends Exception {
11	
12	    private final String lastName;
13	
14	    private final String address;
15	
16	    public DuplicateHouseholdException(String lastName, String address) {
17	        super("An owner named '" + lastName + "' already exists at address '" + address + "'");
18	        this.lastName = lastName;
19	        this.address = address;
20	    }
21	
22	    public String getLastName() {
23	        return this.lastName;
24	    }
25	
26	    public String getAddress() {
27	        return this.address;
28	    }
29	}
